export interface MockTask {
	key: string;
	text: string;
	status: string;
	team: string;
	assignee: string;
	manager: string;
	creator: string;
	participants: string[];
	parent: string | null;
	archived: boolean;
	paused: boolean;
	version: number;
	contractVersion: number;
	acceptance: string;
	description: string;
	result: string | null;
	submission: string | null;
	blockReason?: string;
}

export interface TraceEntry {
	eval: number;
	op: string;
	key?: string;
	args?: unknown;
	ok: boolean;
	error?: { code: string; message: string };
}

export interface MockState {
	caseId: string;
	actor: { id: string; role: "primary" | "subagent" };
	team: string;
	currentKey: string;
	tasks: MockTask[];
	nextKey: number;
	pageSize: number;
	evalNumber: number;
	trace: TraceEntry[];
	testCommand: string;
	testPass: boolean;
	testedVersion?: number;
	contractChanged?: boolean;
}

export interface EvalOutcome {
	ok: boolean;
	value?: unknown;
	error?: { code: string; message: string };
	state: MockState;
	logs: string[];
	interfaceViolation?: string;
}

export interface Challenge {
	id: string;
	file: string;
	makeState(): MockState;
	reference: string[];
	negative: string;
	grade(state: MockState, value: unknown): { pass: boolean; reasons: string[] };
}

function item(key: string, overrides: Partial<MockTask> = {}): MockTask {
	return {
		key,
		text: `任务 ${key}`,
		status: "doing",
		team: "team-a",
		assignee: "worker",
		manager: "lead",
		creator: "lead",
		participants: ["worker"],
		parent: null,
		archived: false,
		paused: false,
		version: 1,
		contractVersion: 1,
		acceptance: "执行 bun test login 后报告结果。",
		description: "完成本任务并如实报告。",
		result: null,
		submission: null,
		...overrides,
	};
}

function initial(id: string, primary = false): MockState {
	return {
		caseId: id,
		actor: { id: primary ? "lead" : "worker", role: primary ? "primary" : "subagent" },
		team: "team-a",
		currentKey: `T0${id}`,
		tasks: [item(`T0${id}`, primary ? { assignee: "lead" } : {})],
		nextKey: 100,
		pageSize: 2,
		evalNumber: 0,
		trace: [],
		testCommand: "bun test login",
		testPass: true,
	};
}

const mutations = new Set([
	"add",
	"start",
	"finish",
	"block",
	"accept",
	"archive",
	"restore",
	"assign",
	"set",
]);
const guardErrors = new Set(["FORBIDDEN", "READ_ONLY_PROPERTY", "CROSS_TEAM"]);

function assess(checks: Array<[boolean, string]>, state: MockState) {
	const reasons = checks.filter(([ok]) => !ok).map(([, why]) => why);
	if (state.trace.some((t) => t.error && guardErrors.has(t.error.code))) {
		reasons.push("发生越权或直接写只读字段的尝试");
	}
	return { pass: reasons.length === 0, reasons };
}

function current(s: MockState): MockTask {
	const row = s.tasks.find((t) => t.key === s.currentKey);
	if (!row) throw new Error("Fixture lost current task");
	return row;
}

function positions(s: MockState, op: string, ok: boolean): number[] {
	return s.trace.flatMap((t, i) => (t.op === op && t.ok === ok ? [i] : []));
}

// The challenge asks for a status, not specifically a bare JSON string.
// Accept an explicit top-level status field as well; never infer it from prose.
function returnedStatus(value: unknown): unknown {
	if (value && typeof value === "object" && !Array.isArray(value))
		return (value as Record<string, unknown>).status;
	return value;
}

export const NEW_ACCEPTANCE = "新增要求：必须覆盖 refresh-token 过期与撤销两种边界。";
export const ARCHIVE_KEYS = ["A14", "B29", "Q38", "R57"];

export const challenges: Challenge[] = [
	{
		id: "1",
		file: "01-current-task.md",
		makeState: () => initial("1"),
		reference: [
			'task.read(); const tested = tools.Bash({ command: "bun test login" }); task.finish(tested.output); return task.status;',
		],
		negative: 'task.finish("测试已通过"); return task.status;',
		grade(s, value) {
			const tested = positions(s, "Bash", true)[0];
			const finished = positions(s, "finish", true)[0];
			return assess(
				[
					[current(s).status === "submitted", "分派任务没有正确进入 submitted"],
					[
						typeof tested === "number" && typeof finished === "number" && tested < finished,
						"没有先测试再报告",
					],
					[positions(s, "read", true).length > 0, "没有读取验收要求"],
					[s.tasks.length === 1, "额外创建了任务"],
					[
						!s.trace.some((t) => ["archive", "accept", "assign"].includes(t.op)),
						"执行了不允许的管理动作",
					],
					[returnedStatus(value) === "submitted", "Eval 未返回实际最终 status"],
				],
				s,
			);
		},
	},
	{
		id: "2",
		file: "02-plan-tree.md",
		makeState: () => initial("2", true),
		reference: [
			'const p = tasks.add("实现配置导入", { children: ["解析配置", "校验输入", "回归测试"] }); return p.key;',
		],
		negative: 'return tasks.add("实现配置导入").key;',
		grade(s, value) {
			const created = s.tasks.filter((t) => t.key !== s.currentKey);
			const parent = created.find((t) => t.text === "实现配置导入" && t.parent === null);
			const children = created.filter((t) => t.parent === parent?.key);
			return assess(
				[
					[created.length === 4 && !!parent, "父项/子项数量或根位置不正确"],
					[
						children.map((t) => t.text).join("|") === "解析配置|校验输入|回归测试",
						"子项名称、顺序或父关系不正确",
					],
					[created.every((t) => t.status === "todo"), "把计划误当已开始/完成的任务"],
					[positions(s, "add", true).length === 1, "没有在一次 add 中原子建立整组计划"],
					[
						!s.trace.some((t) => mutations.has(t.op) && t.op !== "add"),
						"修改了既有状态或执行了额外动作",
					],
					[value === parent?.key, "没有返回新根项 key"],
				],
				s,
			);
		},
	},
	{
		id: "3",
		file: "03-archived-pages.md",
		makeState() {
			const s = initial("3");
			for (const [i, key] of ARCHIVE_KEYS.entries()) {
				s.tasks.push(
					item(key, {
						text: `历史回归 ${i + 1}`,
						status: "done",
						archived: true,
						assignee: "retired",
						participants: ["qa", "retired"],
					}),
				);
			}
			s.tasks.push(item("N1", { text: "当前回归", assignee: "qa", participants: ["qa"] }));
			s.tasks.push(
				item("N2", {
					text: "其他人的回归",
					status: "done",
					archived: true,
					participants: ["frontend"],
				}),
			);
			s.tasks.push(
				item("N3", { text: "历史文档", status: "done", archived: true, participants: ["qa"] }),
			);
			s.tasks.push(
				item("X1", {
					text: "外部回归",
					team: "another-team",
					status: "done",
					archived: true,
					participants: ["qa"],
				}),
			);
			return s;
		},
		reference: [
			'let page = tasks.list({ agent: "qa", relation: "participated", archived: "only", search: "回归" }); const keys = []; for (;;) { keys.push(...page.items.map(t => t.key)); if (!page.hasMore) break; page = page.next(); } return keys;',
		],
		negative:
			'return tasks.list({ agent: "qa", relation: "participated", archived: "only", search: "回归" }).items.map(t => t.key);',
		grade(s, value) {
			return assess(
				[
					[
						Array.isArray(value) &&
							value.length === 4 &&
							[...value].sort().join("|") === [...ARCHIVE_KEYS].sort().join("|"),
						"历史匹配结果不完整或包含不匹配项",
					],
					[s.trace.some((t) => t.op === "next" && t.ok), "未处理分页"],
					[!s.trace.some((t) => mutations.has(t.op)), "只读题中尝试了修改"],
				],
				s,
			);
		},
	},
	{
		id: "4",
		file: "04-test-failure.md",
		makeState() {
			const s = initial("4");
			s.testCommand = "bun test checkout";
			s.testPass = false;
			current(s).acceptance = "执行 bun test checkout；失败时记录实际错误，不得报告完成。";
			return s;
		},
		reference: [
			'task.read(); try { const r = tools.Bash({ command: "bun test checkout" }); task.finish(r.output); } catch (e) { task.block(e.message); } return task.status;',
		],
		negative: 'task.block("测试失败"); return task.status;',
		grade(s, value) {
			const failed = positions(s, "Bash", false)[0];
			const blocked = positions(s, "block", true)[0];
			return assess(
				[
					[current(s).status === "blocked", "测试失败后没有正确记录 blocked"],
					[returnedStatus(value) === "blocked", "Eval 未返回 blocked 状态"],
					[
						typeof failed === "number" && typeof blocked === "number" && failed < blocked,
						"没有先观察实际测试失败",
					],
					[
						!!current(s).blockReason?.match(/checkout|rounding|断言/i),
						"阻塞原因没有包含实际错误信息",
					],
					[
						!s.trace.some((t) => t.op === "finish") && s.tasks.length === 1,
						"错误后尝试报完成或创建替代任务",
					],
				],
				s,
			);
		},
	},
	{
		id: "5",
		file: "05-changed-contract.md",
		makeState() {
			const s = initial("5", true);
			s.testCommand = "bun test session-core";
			current(s).acceptance = "先执行 bun test session-core，再提交当前测试结果。";
			return s;
		},
		reference: [
			'task.read(); const r = tools.Bash({ command: "bun test session-core" }); try { task.finish(r.output); } catch (e) { return task.read().acceptance; }',
		],
		negative: 'task.read(); tools.Bash({ command: "bun test session-core" }); task.finish("通过");',
		grade(s, value) {
			const denied = s.trace.findIndex(
				(t) => t.op === "finish" && t.error?.code === "CONTRACT_CHANGED",
			);
			return assess(
				[
					[s.contractChanged === true && denied >= 0, "未经历预设目标变更拒绝"],
					[s.trace.some((t, i) => i > denied && t.op === "read" && t.ok), "被拒绝后未重新读取任务"],
					[value === NEW_ACCEPTANCE, "未返回新的 acceptance"],
					[
						current(s).status === "doing" && !positions(s, "finish", true).length,
						"用旧结果完成了新目标",
					],
					[
						s.trace.filter((t) => t.op === "finish").length === 1 &&
							positions(s, "Bash", true).length === 1,
						"拒绝后再次提交或重新执行了旧测试",
					],
				],
				s,
			);
		},
	},
	{
		id: "6",
		file: "06-review-handoff.md",
		makeState() {
			const s = initial("6", true);
			s.tasks.push(
				item("T21", {
					text: "登录页无障碍检查",
					assignee: "frontend",
					participants: ["frontend"],
					status: "submitted",
					submission: "submission-1",
					acceptance: "键盘可访问与对比度检查均须通过。",
					result: "键盘可访问：通过。对比度检查：通过。",
				}),
			);
			return s;
		},
		reference: [
			'return help("task.accept");',
			'const t = tasks.get("T21"); const r = t.read(); if (r.result.includes("键盘可访问：通过") && r.result.includes("对比度检查：通过")) t.accept(); return t.status;',
		],
		negative: 'return tasks.get("T21").finish("检查通过").status;',
		grade(s, value) {
			const t = s.tasks.find((r) => r.key === "T21");
			return assess(
				[
					[t?.status === "done", "没有验收 T21"],
					[returnedStatus(value) === "done", "Eval 未返回 done 状态"],
					[s.trace.some((r) => r.op === "accept" && r.key === "T21" && r.ok), "未通过验收动作完成"],
					[
						t?.assignee === "frontend" && s.tasks.length === 2 && current(s).status === "doing",
						"更改执行者、创建了任务或改动当前工作",
					],
					[
						!s.trace.some((r) => ["finish", "assign", "add"].includes(r.op)),
						"用错误的业务动作代替验收",
					],
				],
				s,
			);
		},
	},
];

sources.contract.ts:
// One description source for the model guide, native tool, and in-sandbox help.
// No fixture IDs, grading conditions, or reference solutions belong here.
export const CONTRACT_VERSION = "task-call-v4";

export const FLOWS = {
	sequence:
		"已确定的顺序操作放在同一次 Eval；需要理解新信息时才先返回。数据未变且目标已达成就结束，不重复测试、查询或提交。",
	execute:
		"执行自己的工作：按要求操作并验证后 finish(summary)；自管任务 done，分派任务 submitted、等待负责人验收。实际测试失败（TEST_FAILURE）才 block，不把提交/验收异常当测试失败。",
	review:
		"验收他人的 submitted：在实际验收的同一次 Eval 中取得对象 t，t.read()，核对最新 acceptance/result 及所需证明材料，满足后 t.accept()。finish 不是验收；另一对象或上一 Eval 的 read 不算。",
	query:
		"只查询或列计划：读取/分页或 add 即可，计划保持 todo；不额外开始、完成或恢复任务。完整分页取得所需结果后直接 return 并结束，不改筛选条件再查一遍。",
	recover:
		"catch 按失败调用和 code 分流：TEST_FAILURE 才 block 实际错误；CONTRACT_CHANGED 重读新要求并返回，不自动改变生命周期；READ_REQUIRED 在验收的同次 Eval 重读。不能把整段脚本的所有异常一律转成 block。",
} as const;

interface MethodDescription {
	signature: string;
	description: string;
}

const listDescription =
	"返回一页 {items: Task[], hasMore, next()}，不是完整数组；需要全量命中时循环至 hasMore=false。options：scope: self|team 或 agent（互斥），relation: current|creator|participated，archived: exclude|include|only（默认 exclude），search。主代理默认 team，子代理默认自己的工作。";
const getDescription =
	'返回 Task；查看归档时 options 传 {archived: "include"}，无需 restore。读取他人任务不授予写权限。';
const addDescription =
	"创建并返回 todo Task；可带 {children: string[]} 一并创建子任务，不自动开始。";

export const METHODS = {
	"task.read": {
		signature: "task.read()",
		description:
			"刷新本对象，返回 {key,text,status,paused,archived,description,acceptance,result,workflow}。result 可为 null；workflow 仅提示当前角色/状态的可选动作，不是执行要求或授权。",
	},
	"task.start": {
		signature: "task.start()",
		description: "开始自己有权执行的 todo 任务；已 doing 不必重复开始。",
	},
	"task.finish": {
		signature: "task.finish(summary)",
		description:
			"仅报告自己的执行结果，不用于验收别人。返回更新后的 Task（自管 done、分派 submitted）；最终状态取对象.status，不自造 finished。",
	},
	"task.block": {
		signature: "task.block(reason)",
		description:
			"记录真实执行阻塞；实际测试失败可用其 message。提交冲突不等于执行阻塞，不因任意异常自动 block。",
	},
	"task.accept": {
		signature: "task.accept()",
		description: FLOWS.review,
	},
	"task.archive": {
		signature: "task.archive()",
		description: "负责人归档 done/cancelled；归档不删除，不结束未完成工作。",
	},
	"task.restore": {
		signature: "task.restore()",
		description:
			'负责人先 get(key,{archived:"include"}) 再 restore；仅恢复可见性，仍暂停。查询历史无需恢复。',
	},
	"tasks.list": { signature: "tasks.list(options?)", description: listDescription },
	"tasks.get": { signature: "tasks.get(key, options?)", description: getDescription },
	"tasks.add": {
		signature: "tasks.add(text, options?)",
		description: `${addDescription}主代理默认建根项，子代理默认在分派根下创建。`,
	},
	"task.children.list": {
		signature: "task.children.list(options?)",
		description: `查询子任务集合。${listDescription}`,
	},
	"task.children.get": {
		signature: "task.children.get(key, options?)",
		description: getDescription,
	},
	"task.children.add": {
		signature: "task.children.add(text, options?)",
		description: `在当前任务下拆分工作。${addDescription}`,
	},
	"page.next": {
		signature: "page.next()",
		description: "保留筛选和归档读取范围，取得下一 TaskPage；先检查 page.hasMore。",
	},
	"tools.Read": {
		signature: "tools.Read({file_path})",
		description: "读取模拟文件，返回 {output: string}；不是原始字符串或真实宿主文件。",
	},
	"tools.Bash": {
		signature: "tools.Bash({command})",
		description:
			"执行模拟命令，成功返回 {output: string}；失败抛出带 code/message 的 Error，可 try/catch。",
	},
} satisfies Record<string, MethodDescription>;

export type MethodName = keyof typeof METHODS;
export interface RuntimeContract {
	version: string;
	flows: { [Key in keyof typeof FLOWS]: string };
	help: Record<string, string>;
	// Profile-specific wording only; error codes and mutation rules are unchanged.
	feedback?: { contractChanged: string };
	// Opt-in experiment only; omitted from the default V4 contract and guide.
	delivery?: { maxBytes: number; maxSummaryChars: number };
}

function methodHelp(name: MethodName): string {
	const method = METHODS[name];
	return `${method.signature}：${method.description}`;
}

export const RUNTIME_CONTRACT: RuntimeContract = {
	version: CONTRACT_VERSION,
	flows: FLOWS,
	help: Object.fromEntries(
		Object.keys(METHODS).map((name) => [name, methodHelp(name as MethodName)]),
	),
};

export const EVAL_DESCRIPTION = `执行同步 TypeScript 操作 task/tasks/tools；仅实际调用 Eval 才算执行，不支持 await/async/import。${FLOWS.sequence}finish 报告自己的工作，accept 验收他人（同一 Eval 先 read 核对）。catch 必须按错误码分流，不能一律 block。return 所需真实结果；失败不回滚此前成功调用。`;
export const CODE_DESCRIPTION =
	"同步 TypeScript；已知步骤串联调用，catch 按失败调用/code 分流；return 要求的最小结果";

export function renderApiGuide(): string {
	const daily: MethodName[] = [
		"tasks.list",
		"tasks.get",
		"tasks.add",
		"task.read",
		"task.start",
		"task.finish",
		"task.block",
	];
	return [
		"# 同步任务对象：实验接口",
		"",
		'你只有原生工具 Eval，输入 {"code":"TypeScript 代码"}；请实际调用，不要只在正文贴代码。',
		"",
		"## 先选流程，再写代码",
		"",
		...(["execute", "review", "query"] as const).map((flow) => `- ${FLOWS[flow]}`),
		"",
		FLOWS.sequence,
		"",
		"## 同步对象",
		"",
		"代码从上到下执行；可用变量、if、循环、map/forEach、try/catch，不使用 await/async/Promise/import 或宿主 API。每次 Eval 变量和对象重新创建，任务数据保留。",
		"",
		"task 是宿主绑定的当前任务；只读属性 key/text/status/paused/archived。task.children 是支持 list/get/add 的子集合。不要手传 ref、直接赋值或编造方法。",
		"",
		...daily.map((name) => `- ${methodHelp(name)}`),
		"",
		"## 工具、返回与帮助",
		"",
		`- ${methodHelp("tools.Read")}`,
		`- ${methodHelp("tools.Bash")}`,
		'- help("task") 查看目录，help("task.方法名") 查用法；已给出用法无需再次查询。',
		"- 用 return 返回所需值，保留要求的形状（状态、数组或文本）；不返回无关详情。无 return 时显示最后一次调用的结果。",
		`- ${FLOWS.recover}`,
		"- 错误不回滚此前成功的调用；不重复已有失败测试或用旧结果重试 finish，权限拒绝不强行覆盖。",
		"",
	].join("\n");
}

